    teams: Dict[TeamColor, List[str]] = field(default_factory=dict)  # color -> [player_ids]
    current_turn: int = 0
    turn_order: List[str] = field(default_factory=list)
    board_state: Dict[str, Any] = field(default_factory=dict)
    chat_history: List[Dict] = field(default_factory=list)
    created_at: float = field(default_factory=time.time)

    def to_dict(self):
        return {
            "id": self.id,
            "name": self.name,
            "challenge_id": self.challenge_id,
            "state": self.state.value,
            "players": {pid: p.to_dict() for pid, p in self.players.items()},
            "teams": {c.value: pids for c, pids in self.teams.items()},
            "current_turn": self.current_turn,
            "turn_order": self.turn_order,
            "board_state": self.board_state,
            "chat_history": self.chat_history,
            "created_at": self.created_at
        }

# =====================
# In-Memory Storage (Simulating DB)
# =====================

class InMemoryDB:
    def __init__(self):
        self.players: Dict[str, Player] = {}
        self.games: Dict[str, Game] = {}
        self.challenges: Dict[str, Challenge] = {}
        self.sessions: Dict[str, str] = {}  # token -> player_id

    def add_player(self, player: Player):
        self.players[player.id] = player

    def get_player(self, player_id: str) -> Optional[Player]:
        return self.players.get(player_id)

    def add_game(self, game: Game):
        self.games[game.id] = game

    def get_game(self, game_id: str) -> Optional[Game]:
        return self.games.get(game_id)

    def add_challenge(self, challenge: Challenge):
        self.challenges[challenge.id] = challenge

    def get_challenge(self, challenge_id: str) -> Optional[Challenge]:
        return self.challenges.get(challenge_id)

    def add_session(self, token: str, player_id: str):
        self.sessions[token] = player_id

    def get_player_by_token(self, token: str) -> Optional[str]:
        return self.sessions.get(token)

